from itertools import combinations
import networkx as nx

# Fixed edges
fixed_edges = [
    (2,5), (8,11), (0,2), (5,9), (2,10), (2,11), (4,13), (7,14), 
    (2,13), (11,14), (4,6), (9,10), (4,14), (12,13), (3,4), (0,7), 
    (1,5), (2,3), (5,8), (11,12), (7,10)
]

# All possible edges
all_edges = list(combinations(range(15), 2))
edge_to_idx = {e: i for i, e in enumerate(all_edges)}

fixed_set = set(fixed_edges)
fixed_indices = set(edge_to_idx[e] for e in fixed_edges)

possible_edges = [e for e in all_edges if e not in fixed_set]
possible_indices = [edge_to_idx[e] for e in possible_edges]

n_possible = len(possible_edges)

# Re-run the SAT solver
from pysat.solvers import Glucose3
from pysat.formula import CNF

cnf = CNF()

# Constraint: Every set of 5 vertices has at least one edge
for five_set in combinations(range(15), 5):
    edges_in_set = []
    for e in combinations(five_set, 2):
        e = tuple(sorted(e))
        if e in fixed_set:
            edges_in_set.append('fixed')
        else:
            idx = edge_to_idx[e]
            var = possible_indices.index(idx) + 1
            edges_in_set.append(var)

    if 'fixed' in edges_in_set:
        continue

    var_edges = [e for e in edges_in_set if e != 'fixed']
    if var_edges:
        cnf.append(var_edges)

# Degree constraints
for v in range(15):
    fixed_degree = sum(1 for e in fixed_edges if v in e)
    possible_incident = []
    for i, e in enumerate(possible_edges):
        if v in e:
            possible_incident.append(i + 1)

    needed = 4 - fixed_degree
    if needed <= 0:
        continue

    m = len(possible_incident) - needed
    for subset in combinations(possible_incident, m + 1):
        cnf.append(list(subset))

solver = Glucose3()
for clause in cnf.clauses:
    solver.add_clause(clause)

if solver.solve():
    model = solver.get_model()

    selected_edges = list(fixed_edges)
    for val in model:
        if val > 0 and val <= n_possible:
            selected_edges.append(possible_edges[val - 1])

    G = nx.Graph()
    G.add_nodes_from(range(15))
    G.add_edges_from(selected_edges)

    # Verify max independent set
    max_is = 0
    for k in range(1, 16):
        found = False
        for subset in combinations(range(15), k):
            is_independent = True
            for u, v in combinations(subset, 2):
                if G.has_edge(u, v):
                    is_independent = False
                    break
            if is_independent:
                found = True
                break
        if found:
            max_is = k
        else:
            break

    print(f"Max independent set size: {max_is}")
    print(f"Vertex connectivity: {nx.node_connectivity(G)}")
    print(f"Number of edges: {len(selected_edges)}")

    if max_is <= 4 and nx.node_connectivity(G) >= 4:
        print("VALID SOLUTION!")
        # Sort edges
        selected_edges_sorted = sorted([tuple(sorted(e)) for e in selected_edges])
        print(f"Edges: {selected_edges_sorted}")
    else:
        print("INVALID")
else:
    print("UNSAT")
